const softDeleteEmailCampaign = `-- name: SoftDeleteEmailCampaign :execrows
UPDATE email_campaigns SET deleted_at = NOW(), updated_at = NOW()
WHERE id = $1 AND deleted_at IS NULL
`

// Soft delete: a sent campaign keeps its recipients, opens and clicks
func (q *Queries) SoftDeleteEmailCampaign(ctx context.Context, id uuid.UUID) (int64, error) {
	result, err := q.db.ExecContext(ctx, softDeleteEmailCampaign, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const updateEmailCampaign = `-- name: UpdateEmailCampaign :execrows
UPDATE email_campaigns
SET name = $1, subject = $2, blocks = $3,
    styles = $4, audience_kind = $5,
    audience_id = $6, email_id = $7,
    ab_enabled = $8, ab_subject_b = $9,
    ab_test_percent = $10, ab_winner_metric = $11,
    ab_test_minutes = $12, updated_at = NOW()
WHERE id = $13 AND status = 'draft'
`

type UpdateEmailCampaignParams struct {
	Name           string          `json:"name"`
	Subject        string          `json:"subject"`
	Blocks         json.RawMessage `json:"blocks"`
	Styles         json.RawMessage `json:"styles"`
	AudienceKind   string          `json:"audience_kind"`
	AudienceID     uuid.NullUUID   `json:"audience_id"`
	EmailID        uuid.NullUUID   `json:"email_id"`
	AbEnabled      bool            `json:"ab_enabled"`
	AbSubjectB     string          `json:"ab_subject_b"`
	AbTestPercent  int32           `json:"ab_test_percent"`
	AbWinnerMetric string          `json:"ab_winner_metric"`
	AbTestMinutes  int32           `json:"ab_test_minutes"`
	ID             uuid.UUID       `json:"id"`
}

// Only drafts are editable
func (q *Queries) UpdateEmailCampaign(ctx context.Context, arg UpdateEmailCampaignParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateEmailCampaign,
		arg.Name,
		arg.Subject,
		arg.Blocks,
		arg.Styles,
		arg.AudienceKind,
		arg.AudienceID,
		arg.EmailID,
		arg.AbEnabled,
		arg.AbSubjectB,
		arg.AbTestPercent,
		arg.AbWinnerMetric,
		arg.AbTestMinutes,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
